/// <summary>
/// getItem response: the released product's name, units and which dimensions its dimension groups activate.
/// </summary>
[DataContractAttribute]
class HSMobileOpsItemResponse
{
    boolean success;
    str errorCode;
    str itemId;
    str itemName;
    str inventUnit;
    str purchUnit;
    boolean batchActive;
    boolean serialActive;
    boolean locationActive;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

